ALTER TABLE users ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'users' AND policyname = 'Allow full access to authenticated and anon'
  ) THEN
    CREATE POLICY "Allow full access to authenticated and anon" ON users FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
  END IF;
END $$;

